package io.lumine.mythic.lib.player.particle.type;
import io.lumine.mythic.lib.player.particle.*;import io.lumine.mythic.lib.util.configobject.ConfigObject;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.math.Vec3d;import java.util.Map;
public class HelixParticleEffect extends ParticleEffect{private final double speed,height,radius,rSpeed,ySpeed;private final int amount;private double a;public HelixParticleEffect(String k,Map<String,Double>m,ParticleInformation p){super(k,p);speed=resolveModifier(m,"speed");height=resolveModifier(m,"height");radius=resolveModifier(m,"radius");rSpeed=resolveModifier(m,"rotation-speed");ySpeed=resolveModifier(m,"y-speed");amount=(int)resolveModifier(m,"amount");}public HelixParticleEffect(ConfigObject o){super(o);speed=o.getDouble("speed");height=o.getDouble("height");radius=o.getDouble("radius");rSpeed=o.getDouble("rotation-speed");ySpeed=o.getDouble("y-speed");amount=o.getInt("amount");}public ParticleEffectType getType(){return ParticleEffectType.HELIX;}public void tick(){ServerPlayerEntity pl=playerData.getPlayer();Vec3d b=pl.getPos();int n=Math.max(1,amount);for(int k=0;k<n;k++){double x=a+k*Math.PI*2/n;particle.display(pl.getServerWorld(),b.add(Math.cos(x)*Math.cos(a*ySpeed)*radius,1+Math.sin(a*ySpeed)*height,Math.sin(x)*Math.cos(a*ySpeed)*radius),speed);}a+=Math.PI/24*rSpeed;if(ySpeed!=0&&a>Math.PI*2/ySpeed)a-=Math.PI*2/ySpeed;}}
